import React, { useEffect, useRef, memo } from 'react';
import './NiftyChart.css';

const NiftyChart = () => {
  const containerRef = useRef();

  useEffect(() => {
    if (containerRef.current) {
        // 1. Completely clear out any old/broken widgets first
        containerRef.current.innerHTML = '';

        // 2. Re-create the exact HTML structure TradingView requires
        const innerDiv = document.createElement('div');
        innerDiv.className = 'tradingview-widget-container__widget';
        containerRef.current.appendChild(innerDiv);

        // 3. Create and inject the working SENSEX script
        const script = document.createElement('script');
        script.src = 'https://s3.tradingview.com/external-embedding/embed-widget-mini-symbol-overview.js';
        script.type = 'text/javascript';
        script.async = true;

        script.innerHTML = JSON.stringify({
          "symbol": "BSE:SENSEX", 
          "width": "100%",
          "height": "350",
          "locale": "en_IN",
          "dateRange": "1M",
          "colorTheme": "light",
          "trendLineColor": "#14C4B5",
          "underLineColor": "rgba(20, 196, 181, 0.3)",
          "underLineBottomColor": "rgba(20, 196, 181, 0)",
          "isTransparent": false,
          "autosize": false,
          "largeChartUrl": ""
        });

        containerRef.current.appendChild(script);
    }
  }, []);

  return (
    <div className="chart-widget-block">
      <h3 className="chart-title">India Market: BSE SENSEX</h3>

      {/* We provide the empty container, and let the code above fill it safely */}
      <div className="tradingview-widget-container" ref={containerRef}></div>

    </div>
  );
};

export default memo(NiftyChart);
